<script setup lang="ts">
import {computed,ref} from 'vue'
import {onLoad,onShow,onHide,onShareAppMessage,onShareTimeline} from '@dcloudio/uni-app'
import {fetchSamples,fetchSample,fetchSampleOptions,assignSample,confirmSample,followupSample,type SampleRequest,type SampleOptions,type SampleReceiver} from '../../api/samples'
import {MiniRequestError} from '../../api/client'
import {useSessionStore} from '../../stores/session'
import {restoreRegistrationSession} from '../../utils/registrationSession'
import {canUseEmployeePriceCenter} from '../../utils/priceCenterAccess'
import {canConfirmSample,validSampleMoney,confirmRows,sampleTotal,sampleStatus,sampleDate,followupOptions,followupLabel} from '../../utils/samples'
import {loginRouteFor} from '../../utils/loginReturn'
import EnvironmentBadge from '../../components/EnvironmentBadge.vue'
import PullUpBrandFooter from '../../components/PullUpBrandFooter.vue'
import { usePullUpBrandGesture } from '../../composables/usePullUpBrandGesture'
import {defaultMiniappShare,defaultMiniappTimelineShare,refreshMiniappShareMenu} from '../../utils/miniappShare'
const {pullUpBrandRevealed,handlePullUpBrandTouchStart,handlePullUpBrandTouchMove,handlePullUpBrandTouchEnd,handlePullUpBrandTouchCancel}=usePullUpBrandGesture()
onShareAppMessage(defaultMiniappShare)
onShareTimeline(defaultMiniappTimelineShare)
onShow(()=>{void refreshMiniappShareMenu()})
const session=useSessionStore(), staff=computed(()=>canUseEmployeePriceCenter(session)), admin=computed(()=>staff.value&&session.roles.includes('admin'))
const id=ref(0), rows=ref<SampleRequest[]>([]), detail=ref<SampleRequest|null>(null), loading=ref(false),busy=ref(false),error=ref(''),page=ref(1),total=ref(0),search=ref(''),status=ref('')
const options=ref<SampleOptions>({customers:[],employees:[],specs:[],sources:[],order_types:[],customer_types:[]})
const customerTypeChoices=computed(()=>options.value.customer_types.map(value=>({value,label:({retail:'零售客户',ecommerce:'电商客户',wholesale:'批发客户',channel:'渠道客户'} as Record<string,string>)[value]||value})))
const employeeID=ref(0),customerID=ref(0),newCustomerMode=ref(false),customerSearch=ref(''),customerName=ref(''),customerType=ref(''),sourceID=ref(0),orderTypeID=ref(0)
const receiver=ref<SampleReceiver>({name:'',phone:'',address:''}),items=ref<ReturnType<typeof confirmRows>>([]),freight=ref(0),note=ref(''),followupStatus=ref('following'),followupNote=ref('')
const selectedItems=computed(()=>items.value.filter(i=>i.selected)), totalAmount=computed(()=>sampleTotal(selectedItems.value,freight.value)), terminal=computed(()=>['won','abandoned'].includes(detail.value?.followup_status||''))
const canConfirm=computed(()=>!!detail.value&&staff.value&&canConfirmSample(detail.value)), confirmValid=computed(()=>selectedItems.value.length>0&&selectedItems.value.every(i=>i.bom_spec_id>0&&Number.isInteger(Number(i.qty))&&Number(i.qty)>0&&Number(i.qty)<=100000&&validSampleMoney(i.unit_price))&&validSampleMoney(freight.value)&&Number.isSafeInteger(Math.round(totalAmount.value*100))&&!!receiver.value.name.trim()&&!!receiver.value.phone.trim()&&!!receiver.value.address.trim()&&(newCustomerMode.value?!!customerName.value.trim()&&!!customerType.value&&sourceID.value>0&&orderTypeID.value>0:customerID.value>0))
const statuses=[{value:'',label:'全部'},{value:'pending_assignment',label:'待分配'},{value:'pending_contact',label:'待联系'},{value:'ordered',label:'已确认寄样'},{value:'closed',label:'跟进结束'}]
function optionName(list:Array<{id:number;name:string}>,value:number){return list.find(i=>i.id===value)?.name||'请选择'}
function pickID(list:Array<{id:number}>,event:any){return list[Number(event.detail.value)]?.id||0}
function specs(productID:number){return options.value.specs.filter(s=>s.product_id===productID)}
function list(){id.value=0;detail.value=null;void load()}
function open(row:SampleRequest){id.value=row.id;void load()}
function reloadList(){page.value=1;void load()}
function changeStatus(e:any){status.value=statuses[Number(e.detail.value)]?.value||'';reloadList()}
function changePage(delta:number){page.value+=delta;void load()}
function login(){uni.navigateTo({url:loginRouteFor(`/pages/sample-requests/sample-requests${id.value?'?id='+id.value:''}`)})}
function home(){uni.navigateTo({url:staff.value?'/pages/home/home':'/pages/bean-list-center/bean-list-center'})}
let sequence=0
onHide(()=>{sequence++;detail.value=null;rows.value=[]})
async function load(){
 const request=++sequence
 loading.value=true;error.value=''
 try{
  await restoreRegistrationSession(session)
  if(request!==sequence)return
  if(session.accountType==='employee'&&!staff.value)throw new Error('只有销售或管理员可以处理样品工单')
  if(!staff.value&&!session.registrationComplete)throw new Error('请先在价格表中心完成昵称和手机号登记')
  if(id.value){const value=await fetchSample(session.token,staff.value,id.value);if(request!==sequence)return;detail.value=value
   if(staff.value){const result=await fetchSampleOptions(session.token,id.value);if(request!==sequence)return;options.value=result;employeeID.value=value.assignee_id;customerID.value=value.customer_id||options.value.suggested_customer_id||0;newCustomerMode.value=false;receiver.value={...value.receiver};items.value=confirmRows(value.items,options.value.specs||[]);freight.value=0;note.value='';customerName.value=value.nickname||value.receiver.name;sourceID.value=0;orderTypeID.value=0;customerType.value='';followupStatus.value=terminal.value?value.followup_status:'following';followupNote.value=''}
  }else{detail.value=null;const result=await fetchSamples(session.token,staff.value,{q:search.value,status:status.value,page:page.value});if(request!==sequence)return;rows.value=result.rows||[];total.value=result.total}
 }catch(e){if(request!==sequence)return;detail.value=null;rows.value=[];error.value=e instanceof Error?e.message:'加载失败，请重试'}finally{if(request===sequence)loading.value=false}
}
async function run(action:()=>Promise<SampleRequest>,success:string){if(busy.value)return;const request=sequence,requestID=id.value,token=session.token;busy.value=true;error.value='';try{const result=await action();if(request!==sequence||requestID!==id.value||token!==session.token)return;detail.value=result;uni.showToast({title:success,icon:'success'});await load()}catch(e){if(request!==sequence||requestID!==id.value||token!==session.token)return;error.value=e instanceof Error?e.message:'操作失败，请重试';if(e instanceof MiniRequestError&&e.statusCode===409)uni.showToast({title:'工单已更新，请重新加载后处理',icon:'none'})}finally{busy.value=false}}
function assign(){if(!detail.value||!employeeID.value)return;const row=detail.value;void run(()=>assignSample(session.token,row.id,row.revision,employeeID.value),'已分配负责人')}
async function searchCustomers(){if(!detail.value||busy.value)return;const request=sequence,requestID=id.value;busy.value=true;try{const result=await fetchSampleOptions(session.token,id.value,customerSearch.value);if(request!==sequence||requestID!==id.value)return;options.value={...options.value,customers:result.customers||[]};if(!options.value.customers.some(i=>i.id===customerID.value))customerID.value=0}catch(e){if(request!==sequence)return;error.value=e instanceof Error?e.message:'查找客户失败'}finally{busy.value=false}}
function confirm(){if(!detail.value||!confirmValid.value)return;const row=detail.value;uni.showModal({title:'确认已联系客户并寄样',content:`商品 ¥${sampleTotal(selectedItems.value,0).toFixed(2)} + 运费 ¥${Number(freight.value).toFixed(2)} = 合计 ¥${totalAmount.value.toFixed(2)}。确认后生成正式销售订单。`,success:result=>{if(result.confirm)void run(()=>confirmSample(session.token,row.id,{revision:row.revision,customer_id:newCustomerMode.value?0:customerID.value,...(newCustomerMode.value?{new_customer:{name:customerName.value.trim(),customer_type:customerType.value,source_id:sourceID.value,order_type_id:orderTypeID.value}}:{}),receiver:{...receiver.value},items:selectedItems.value.map(i=>({product_id:i.product_id,bom_spec_id:i.bom_spec_id,qty:Number(i.qty),unit_price:Number(i.unit_price)})),shipping_amount:Number(freight.value),note:note.value.trim()}),'订单已生成')}})}
function followup(){if(!detail.value||!followupNote.value.trim())return;const row=detail.value;const execute=()=>run(()=>followupSample(session.token,row.id,row.revision,followupStatus.value,followupNote.value.trim()),'回访已保存');if(['won','abandoned'].includes(followupStatus.value)){uni.showModal({title:`确认${followupLabel(followupStatus.value)}`,content:'保存后停止样品回访提醒，已生成的订单仍按原流程处理。',success:r=>{if(r.confirm)void execute()}})}else void execute()}
onLoad(q=>{id.value=Number(q?.id)||0})
onShow(()=>{void load()})
</script>
<template><view class="page pull-up-brand-page" @touchstart="handlePullUpBrandTouchStart" @touchmove="handlePullUpBrandTouchMove" @touchend="handlePullUpBrandTouchEnd" @touchcancel="handlePullUpBrandTouchCancel"><EnvironmentBadge/><view class="heading"><text class="title">{{staff?'样品工单':'我的样品申请'}}</text><button size="mini" @tap="home">{{staff?'员工首页':'价格表中心'}}</button></view>
<button v-if="id" class="back" @tap="list">返回申请列表</button>
<view v-if="error" class="error"><text>{{error}}</text><button :disabled="busy" @tap="load">重新加载</button><button v-if="!session.token" @tap="login">登录</button></view>
<text v-if="loading" class="state">正在加载…</text>
<template v-else-if="!id"><view class="filters"><input v-model="search" placeholder="搜索申请编号、客户或电话" confirm-type="search" @confirm="reloadList"/><button size="mini" @tap="reloadList">搜索</button><picker :range="statuses" range-key="label" @change="changeStatus"><view class="picker">{{statuses.find(s=>s.value===status)?.label||'全部'}} ▾</view></picker></view>
<text v-if="!rows.length&&!error" class="state">暂无样品申请</text><view v-for="row in rows" :key="row.id" class="card clickable" @tap="open(row)"><view class="line"><text class="strong">{{row.number}}</text><text class="tag">{{sampleStatus(row.status)}}</text></view><text>{{row.publication_name}} · {{row.publication_version}}</text><text class="muted">{{row.items.map(i=>i.name).join('、')}}</text><text>{{row.receiver.name}} · {{row.receiver.phone}}</text><text v-if="staff" class="muted">负责人：{{row.assignee_name||'待分配'}} · {{followupLabel(row.followup_status)}}</text><text class="muted">{{sampleDate(row.created_at)}} →</text></view>
<view v-if="total" class="pagination"><button size="mini" :disabled="page<=1" @tap="changePage(-1)">上一页</button><text>{{page}} / {{Math.ceil(total/20)}} · {{total}} 份</text><button size="mini" :disabled="page*20>=total" @tap="changePage(1)">下一页</button></view></template>
<template v-else-if="detail"><view class="card"><view class="line"><text class="strong">{{detail.number}}</text><text class="tag">{{sampleStatus(detail.status)}}</text></view><text>{{detail.publication_name}} · {{detail.publication_version}}</text><text v-for="item in detail.items" :key="item.key">{{item.name}}</text><text>收件人：{{detail.receiver.name}} · {{detail.receiver.phone}}</text><text>地址：{{detail.receiver.address}}</text><text v-if="detail.note">留言：{{detail.note}}</text><text>负责人：{{detail.assignee_name||'待分配'}}</text><text v-if="detail.order_no">关联订单：{{detail.order_no}}</text><text v-if="detail.order_no">履约进度：{{detail.shipment_status||'待发货'}}</text><text v-if="staff">回访：{{followupLabel(detail.followup_status)}}<text v-if="detail.next_reminder_at"> · 下次提醒 {{sampleDate(detail.next_reminder_at)}}</text></text><text v-if="!staff" class="muted">工作人员将联系您，对接样品规格、数量和费用。</text></view>
<view v-if="staff&&detail.confirmation" class="card"><text class="strong">确认寄样记录</text><text v-for="item in detail.confirmation.items" :key="item.product_id+':'+item.bom_spec_id">{{detail.items.find(p=>p.product_id===item.product_id)?.name}} · {{item.spec_name||'已确认规格'}} · {{item.qty}} {{item.unit||'份'}} × ¥{{Number(item.unit_price).toFixed(2)}}</text><text>收件人：{{detail.confirmation.receiver.name}} · {{detail.confirmation.receiver.phone}}</text><text>寄送地址：{{detail.confirmation.receiver.address}}</text><text>商品 ¥{{sampleTotal(detail.confirmation.items,0).toFixed(2)}} + 运费 ¥{{Number(detail.confirmation.shipping_amount).toFixed(2)}} = 合计 ¥{{sampleTotal(detail.confirmation.items,detail.confirmation.shipping_amount).toFixed(2)}}</text><text v-if="detail.confirmation.note">说明：{{detail.confirmation.note}}</text></view>
<view v-if="admin&&!terminal" class="card"><text class="strong">{{detail.work_order_id?'改派负责人':'分配负责人'}}</text><picker :range="options.employees" range-key="name" :disabled="busy" @change="employeeID=pickID(options.employees,$event)"><view class="picker">{{optionName(options.employees,employeeID)}} ▾</view></picker><button class="primary" :disabled="busy||!employeeID||employeeID===detail.assignee_id" @tap="assign">{{detail.work_order_id?'确认改派':'分配并生成工单'}}</button><text class="muted">改派保留历史和原回访时间。</text></view>
<view v-if="canConfirm" class="card"><text class="strong">已联系客户 · 确认寄样</text><text class="muted">请确认客户、收件信息、有效规格、数量与费用后生成订单。</text><view class="line"><button size="mini" :class="{selected:!newCustomerMode}" :disabled="busy" @tap="newCustomerMode=false">选择已有客户</button><button size="mini" :class="{selected:newCustomerMode}" :disabled="busy" @tap="newCustomerMode=true">新建客户</button></view>
<template v-if="!newCustomerMode"><view class="line"><input v-model="customerSearch" placeholder="查找客户名称或电话" @confirm="searchCustomers"/><button size="mini" :disabled="busy" @tap="searchCustomers">查找</button></view><picker :range="options.customers" range-key="name" :disabled="busy" @change="customerID=pickID(options.customers,$event)"><view class="picker">{{optionName(options.customers,customerID)}} ▾</view></picker><text class="muted">优先确认已绑定客户；候选客户需要核对后选择。</text></template>
<template v-else><label>客户名称<input v-model="customerName" :disabled="busy" maxlength="100" placeholder="客户名称"/></label><label>客户类型<picker :range="customerTypeChoices" range-key="label" :disabled="busy" @change="customerType=customerTypeChoices[Number($event.detail.value)].value"><view class="picker">{{customerTypeChoices.find(i=>i.value===customerType)?.label||'请选择'}} ▾</view></picker></label><label>客户来源<picker :range="options.sources" range-key="name" :disabled="busy" @change="sourceID=pickID(options.sources,$event)"><view class="picker">{{optionName(options.sources,sourceID)}} ▾</view></picker></label><label>默认订单类型<picker :range="options.order_types" range-key="name" :disabled="busy" @change="orderTypeID=pickID(options.order_types,$event)"><view class="picker">{{optionName(options.order_types,orderTypeID)}} ▾</view></picker></label><text class="muted">新客户归工单负责人；建档不会自动开通客户门户。</text></template>
<label>收件人<input v-model="receiver.name" :disabled="busy" maxlength="100"/></label><label>收件电话<input v-model="receiver.phone" :disabled="busy" maxlength="32"/></label><label>收件地址<textarea v-model="receiver.address" :disabled="busy" maxlength="500"/></label>
<view v-for="item in items" :key="item.product_id" class="item"><button size="mini" :disabled="busy" :class="{selected:item.selected}" @tap="item.selected=!item.selected">{{item.selected?'✓ 寄样':'暂不寄样'}} · {{item.name}}</button><template v-if="item.selected"><picker :range="specs(item.product_id)" range-key="name" :disabled="busy" @change="item.bom_spec_id=pickID(specs(item.product_id),$event)"><view class="picker">{{optionName(specs(item.product_id),item.bom_spec_id)}} ▾</view></picker><text v-if="!specs(item.product_id).length" class="error-text">尚无有效已发布规格，请先在 ERP 配置样品 BOM 规格。</text><view class="line"><label>数量<input v-model.number="item.qty" :disabled="busy" type="number"/></label><label>商品单价（元）<input v-model.number="item.unit_price" :disabled="busy" type="digit"/></label></view><text>商品金额 ¥{{sampleTotal([item],0).toFixed(2)}}</text></template></view>
<text v-if="!validSampleMoney(freight)||selectedItems.some(item=>!validSampleMoney(item.unit_price))" class="error-text">金额需明确填写，免费填 0，最多保留两位小数。</text><label>运费（元）<input v-model.number="freight" :disabled="busy" type="digit"/></label><label>确认说明（可选）<textarea v-model="note" :disabled="busy" maxlength="2000"/></label><text class="strong">商品 ¥{{sampleTotal(selectedItems,0).toFixed(2)}} + 运费 ¥{{Number(freight||0).toFixed(2)}} = 合计 ¥{{totalAmount.toFixed(2)}}</text><button class="primary" :disabled="busy||!confirmValid" :loading="busy" @tap="confirm">已联系并确认寄样 · 生成订单</button></view>
<view v-if="staff&&detail.work_order_id&&!terminal" class="card"><text class="strong">记录回访</text><picker :range="followupOptions" range-key="label" :disabled="busy" @change="followupStatus=followupOptions[Number($event.detail.value)].value"><view class="picker">{{followupLabel(followupStatus)}} ▾</view></picker><textarea v-model="followupNote" :disabled="busy" maxlength="2000" placeholder="填写本次回访结果（必填）"/><button class="primary" :disabled="busy||!followupNote.trim()" @tap="followup">保存回访记录</button><text class="muted">有效回访后重新计时 7 天。成交、放弃停止提醒；发货和签收不停止提醒。</text></view>
<view v-if="staff&&detail.activities?.length" class="card"><text class="strong">处理历史</text><view v-for="activity in detail.activities" :key="activity.id" class="history"><text>{{activity.note}}</text><text v-if="activity.status">{{followupLabel(activity.status)}}</text><text class="muted">{{activity.actor}} · {{sampleDate(activity.created_at)}}</text></view></view>
</template><view class="pull-up-brand-footer-anchor"><PullUpBrandFooter :revealed="pullUpBrandRevealed" /></view></view></template>
<style scoped>
.page{min-height:100vh;box-sizing:border-box;background:#f5f4ef;padding:28rpx 24rpx 60rpx;color:#253d31;font-size:28rpx}.heading,.line,.pagination{display:flex;align-items:center;justify-content:space-between;gap:16rpx}.heading{margin:16rpx 0 28rpx}.title{font-weight:800;font-size:38rpx}.heading button{margin:0;flex-shrink:0}.back{font-size:26rpx;background:#edf3e9;color:#285d3e;margin-bottom:20rpx}.card{padding:28rpx;border-radius:18rpx;background:#fff;margin:20rpx 0;display:flex;flex-direction:column;gap:18rpx;overflow-wrap:anywhere}.strong{font-weight:700;font-size:30rpx}.tag{font-size:23rpx;background:#edf4eb;color:#356144;padding:6rpx 12rpx;border-radius:8rpx;flex-shrink:0}.muted{font-size:24rpx;color:#728075;line-height:1.7}.picker{padding:20rpx;background:#f2f5ee;border-radius:10rpx;font-size:27rpx;min-height:38rpx}.primary{background:#285d3e;color:#fff;width:100%;font-size:28rpx}.filters{display:flex;flex-wrap:wrap;gap:12rpx;align-items:center}.filters input{flex:1;min-width:220rpx}.filters button{margin:0}.state{display:block;padding:70rpx 20rpx;text-align:center;color:#7b857d}.error{padding:24rpx;background:#fff1ef;color:#b42318;white-space:pre-wrap;border-radius:14rpx}.error-text{color:#b42318;font-size:25rpx}.error button{font-size:26rpx;margin-top:18rpx}.pagination{font-size:24rpx;margin-top:24rpx}.pagination button{margin:0}label{display:block;font-size:26rpx;flex:1;min-width:0}input,textarea{box-sizing:border-box;width:100%;font-size:28rpx;background:#f2f5ee;border:1rpx solid #e3e9df;border-radius:10rpx;padding:18rpx;margin-top:8rpx}input{height:80rpx}textarea{height:150rpx}.line input{min-width:0}.line button{margin:0;flex-shrink:0}.selected{background:#dcebd6;color:#285d3e}.item{padding:24rpx 0;border-top:1rpx solid #e2e8dd;display:flex;flex-direction:column;gap:16rpx}.item button{white-space:normal;line-height:1.6;text-align:left;padding:16rpx;margin:0}.history{border-top:1rpx solid #e4e8e0;padding-top:18rpx;display:flex;flex-direction:column;gap:8rpx}
</style>
